<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { createGroupRequirement, getCollabGroup, type CollabGroup } from '../api/collab-groups.api'
import { COLLAB_STAGES, type ApprovalLevel } from '../api/collab-projects.api'

const route=useRoute();const router=useRouter();const groupKey=computed(()=>String(route.params.groupKey));const group=ref<CollabGroup|null>(null);const loading=ref(true);const saving=ref(false);const error=ref('');const name=ref('');const description=ref('');const approvalLevel=ref<ApprovalLevel>('L1');const included=ref<string[]>([]);const noApproval=ref<string[]>([])
const stageRows=computed(()=>COLLAB_STAGES.map(s=>({ ...s, template:group.value?.stages?.find(t=>t.stageKey===s.key) })))
function reviewerSummary(stageKey:string){if(approvalLevel.value==='L3')return'自动流转';if(approvalLevel.value==='L2'&&noApproval.value.includes(stageKey))return'本阶段无需审批';const template=stageRows.value.find(s=>s.key===stageKey)?.template;const names=template?.reviewerRoleNames?.length?template.reviewerRoleNames:template?.reviewerRoleName?[template.reviewerRoleName]:[];if(approvalLevel.value==='L2'&&!(template?.reviewerUserIds?.length))return'未配置审批人 · 自动流转';return names.join('、')||'未配置审批人 · 自动流转'}
function inheritedReviewerCount(stageKey:string){return stageRows.value.find(s=>s.key===stageKey)?.template?.reviewerUserIds?.length||0}
function msg(e:unknown){const data=(e as{response?:{data?:{message?:string;code?:string}}})?.response?.data;return data?.message||data?.code||(e as Error)?.message||'请求失败'}
async function load(){loading.value=true;try{group.value=await getCollabGroup(groupKey.value);if(group.value.status!=='PUBLISHED')error.value='项目组尚未推送，暂不能创建需求';else if(!group.value.gitlabRootUrl)error.value='该项目组尚未配置 GitLab 根目录，暂不能创建需求';included.value=(approvalLevel.value==='L1'?COLLAB_STAGES.map(s=>s.key):(group.value.stages||[]).filter(s=>s.included).map(s=>s.stageKey))}catch(e){error.value=msg(e)}finally{loading.value=false}}
function setApproval(value:ApprovalLevel){approvalLevel.value=value;if(value==='L1')included.value=COLLAB_STAGES.map(s=>s.key)}
async function create(){if(!name.value.trim()){error.value='请填写需求名称';return}if(!included.value.length){error.value='至少选择一个阶段';return}saving.value=true;error.value='';try{const req=await createGroupRequirement(groupKey.value,{name:name.value.trim(),description:description.value.trim(),approvalLevel:approvalLevel.value,includedStageKeys:included.value,stagesWithoutApproval:approvalLevel.value==='L2'?noApproval.value.filter(key=>included.value.includes(key)):[],expectedTemplateVersion:group.value?.templateVersion||0});await router.push({name:'collab-requirement-detail',params:{requirementKey:req.requirementKey}})}catch(e){error.value=msg(e)}finally{saving.value=false}}
onMounted(load)
</script>

<template><main class="page"><button class="back" @click="router.push({name:'collab-group-detail',params:{groupKey}})">← {{group?.name||'项目组'}}</button><div v-if="error" class="error">{{error}}</div><div v-if="loading" class="empty">正在加载模板…</div><template v-else-if="group"><header><span class="eyebrow">NEW REQUIREMENT · {{group.name}}</span><h1>新建需求</h1><p>新需求将继承项目组当前模板 v{{group.templateVersion}}。岗位结构和 GitLab/Wiki 配置来自项目组。</p></header><form class="panel" @submit.prevent="create"><label>需求名称 <b>*</b><input v-model="name" required maxlength="160" placeholder="例如：理赔流程增加双人复核"></label><label>需求说明<textarea v-model="description" rows="3" maxlength="4000" placeholder="目标、背景和范围"></textarea></label><fieldset><legend>审批策略</legend><div class="levels"><label v-for="level in (['L1','L2','L3'] as ApprovalLevel[])" :key="level" class="level" :class="{selected:approvalLevel===level}"><input type="radio" name="level" :checked="approvalLevel===level" @change="setApproval(level)"><strong>{{level}}</strong><span>{{level==='L1'?'每阶段审批':level==='L2'?'继承审批人，按阶段可选':'自动流转'}}</span></label></div></fieldset><fieldset><legend>纳入流程阶段 <b>*</b></legend><p>新需求会继承项目组各阶段的负责人和审批人配置。L2 可在创建时为阶段取消审批，也可在需求创建后调整未开始阶段；某阶段所有审批人留空时自动流转，配置多个审批角色时每个角色都需至少一人通过。L1 每阶段审批，L3 全程自动流转。至少保留一个阶段。</p><div class="stage-list"><article v-for="s in stageRows" :key="s.key" class="stage"><input v-model="included" type="checkbox" :value="s.key" :disabled="approvalLevel==='L1'"><strong>{{s.title}}</strong><span>负责人角色：{{s.template?.ownerRoleName||'未配置'}}</span><span>审批角色：{{reviewerSummary(s.key)}}</span><label v-if="approvalLevel==='L2'&&included.includes(s.key)&&inheritedReviewerCount(s.key)" class="approval-toggle"><input v-model="noApproval" type="checkbox" :value="s.key">本阶段无需审批</label><small v-else-if="approvalLevel==='L2'&&included.includes(s.key)">项目组未配置审批人，本阶段自动流转</small><small v-if="!s.template?.included">项目组模板默认跳过</small></article></div></fieldset><div class="actions"><button type="button" class="secondary" @click="router.back()">取消</button><button class="primary" :disabled="saving||group.status!=='PUBLISHED'||!group.gitlabRootUrl">{{saving?'创建中…':'创建需求'}}</button></div></form></template></main></template>

<style scoped>
.page{max-width:930px;margin:auto;padding:30px 30px 70px;color:var(--text-1)}.back{padding:0 0 20px;border:0;background:none;color:var(--text-2);cursor:pointer}.eyebrow{font:700 10px var(--font-mono);letter-spacing:.15em;color:var(--accent-400)}h1{margin:7px 0;font-size:30px}header p{color:var(--text-2);margin:0 0 20px}.panel{display:grid;gap:17px;padding:22px;border:1px solid var(--border-1);border-radius:12px;background:var(--surface-1)}.panel>label{display:grid;gap:7px;color:var(--text-2);font-size:13px;font-weight:650}.panel input:not([type=radio]):not([type=checkbox]),textarea{box-sizing:border-box;width:100%;padding:10px 12px;border:1px solid var(--border-2);border-radius:8px;background:var(--surface-2);color:var(--text-1);font:inherit}.panel b{color:var(--error)}fieldset{border:1px solid var(--border-1);border-radius:9px;padding:13px}legend{padding:0 6px;font-weight:700;font-size:13px}fieldset p{color:var(--text-3);font-size:12px;margin:0 0 11px}.levels{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.level{display:grid;grid-template-columns:auto 1fr;gap:5px 8px;padding:11px;border:1px solid var(--border-1);border-radius:8px;background:var(--surface-2);cursor:pointer}.level strong{color:var(--accent-400)}.level span{grid-column:2;font-size:11px;color:var(--text-3)}.level.selected{border-color:var(--accent-500);background:var(--accent-softer)}.stage-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.stage{display:grid;grid-template-columns:auto 1fr;gap:6px 9px;padding:10px;border:1px solid var(--border-1);border-radius:8px}.stage>input{grid-row:span 3;accent-color:var(--accent-500)}.stage strong{font-size:12px}.stage span,.stage small{font-size:10px;color:var(--text-3)}.stage small{color:var(--warning)}.approval-toggle{grid-column:2;display:flex;align-items:center;gap:6px;color:var(--text-2);font-size:11px}.approval-toggle input{margin:0;accent-color:var(--accent-500)}.actions{display:flex;justify-content:flex-end;gap:9px}.primary,.secondary{padding:10px 15px;border:0;border-radius:8px;cursor:pointer;font-weight:650}.primary{background:var(--accent-600);color:white}.secondary{background:var(--surface-3);color:var(--text-1)}button:disabled{opacity:.5}.error{padding:10px;margin-bottom:12px;border-radius:8px;background:var(--error-soft);color:var(--error)}.empty{display:grid;place-items:center;min-height:180px;color:var(--text-3)}@media(max-width:650px){.page{padding:22px 15px}.levels,.stage-list{grid-template-columns:1fr}}
</style>
